"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View5 from "./components/feature-sections/variants/06-signal-grid";
const variants = {"signal-grid":View5};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "signal-grid"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "signal-grid", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { CardFx } from "./06-signal-grid/card-fx";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    badge: "One connected system",
    headline: "Scattered context.",
    headlineAccent: "One clear next step.",
    subhead: "Bring knowledge, decisions, and execution into the same operating layer. Every signal stays visible from input to outcome.",
    items: [
        { title: "Connected orchestration", description: "Keep every step, handoff, and decision connected from request to outcome." },
        { title: "Context-aware execution", description: "Bring the right knowledge into each task before the work begins." },
        { title: "Built-in guardrails", description: "Apply clear boundaries exactly where sensitive actions need them." },
        { title: "Persistent memory", description: "Carry useful context forward without making users repeat themselves." },
        { title: "Structured outputs", description: "Turn every result into predictable data that other systems can use." },
        { title: "Human approval", description: "Keep people in control when a decision needs review or confirmation." },
    ],
} satisfies ArtemisFeatureContent;
const HIDDEN = { opacity: 0, transform: "translateY(16px)" };
const SHOWN = { opacity: 1, transform: "translateY(0px)" };
function GitBranchIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-git-branch ${className}`} aria-hidden="true">
      <path d="M15 6a9 9 0 0 0-9 9V3"/>
      <circle cx="18" cy="6" r="3"/>
      <circle cx="6" cy="18" r="3"/>
    </svg>);
}
function LibraryIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-library ${className}`} aria-hidden="true">
      <path d="m16 6 4 14"/>
      <path d="M12 6v14"/>
      <path d="M8 8v12"/>
      <path d="M4 4v16"/>
    </svg>);
}
function ShieldCheckIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-shield-check ${className}`} aria-hidden="true">
      <path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/>
      <path d="m9 12 2 2 4-4"/>
    </svg>);
}
function BrainIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-brain ${className}`} aria-hidden="true">
      <path d="M12 18V5"/>
      <path d="M15 13a4.17 4.17 0 0 1-3-4 4.17 4.17 0 0 1-3 4"/>
      <path d="M17.598 6.5A3 3 0 1 0 12 5a3 3 0 1 0-5.598 1.5"/>
      <path d="M17.997 5.125a4 4 0 0 1 2.526 5.77"/>
      <path d="M18 18a4 4 0 0 0 2-7.464"/>
      <path d="M19.967 17.483A4 4 0 1 1 12 18a4 4 0 1 1-7.967-.517"/>
      <path d="M6 18a4 4 0 0 1-2-7.464"/>
      <path d="M6.003 5.125a4 4 0 0 0-2.526 5.77"/>
    </svg>);
}
function BracesIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-braces ${className}`} aria-hidden="true">
      <path d="M8 3H7a2 2 0 0 0-2 2v5a2 2 0 0 1-2 2 2 2 0 0 1 2 2v5c0 1.1.9 2 2 2h1"/>
      <path d="M16 21h1a2 2 0 0 0 2-2v-5c0-1.1.9-2 2-2a2 2 0 0 1-2-2V5a2 2 0 0 0-2-2h-1"/>
    </svg>);
}
function UserCheckIcon({ className }: { className?: string }) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-user-check ${className}`} aria-hidden="true">
      <path d="m16 11 2 2 4-4"/>
      <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/>
      <circle cx="9" cy="7" r="4"/>
    </svg>);
}
const ICONS = [GitBranchIcon, LibraryIcon, ShieldCheckIcon, BrainIcon, BracesIcon, UserCheckIcon];
/** A card's borders, so the grid draws one line between cards at one, two and three columns. */
function cardClass(i: number, count: number) {
    const last = i === count - 1;
    const bottom2 = i >= Math.floor((count - 1) / 2) * 2;
    const bottom3 = i >= Math.floor((count - 1) / 3) * 3;
    return [
        "art:group art:relative art:flex art:min-h-56 art:flex-col art:overflow-hidden art:border-border art:px-7 art:py-10",
        last ? "" : "art:border-b",
        bottom2 ? "art:@min-[640px]/artemis:border-b-0" : "art:@min-[640px]/artemis:border-b",
        last || i % 2 === 1 ? "art:@min-[640px]/artemis:border-r-0" : "art:@min-[640px]/artemis:border-r",
        bottom3 ? "art:@min-[1024px]/artemis:border-b-0" : "art:@min-[1024px]/artemis:border-b",
        last || i % 3 === 2 ? "art:@min-[1024px]/artemis:border-r-0" : "art:@min-[1024px]/artemis:border-r",
    ].filter(Boolean).join(" ");
}
export default function FeatureSectionsSignalGrid({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const items: ArtemisFeatureItem[] = copy.items;
    const reduce = useReducedMotion();
    const [hovered, setHovered] = useState<number | null>(null);
    const reveal = (i: number) => ({
        onHoverStart: () => setHovered(i),
        onHoverEnd: () => setHovered((h) => (h === i ? null : h)),
        initial: HIDDEN,
        whileInView: SHOWN,
        viewport: { once: true, margin: "-48px" },
        transition: reduce ? { duration: 0 } : { duration: 0.45, delay: i * 0.05, ease: ARTEMIS_EASE_OUT },
    });
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:bg-background art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:mx-auto art:max-w-3xl art:text-center">
              {copy.badge ? (<p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-widest">
                {copy.badge}
              </p>) : null}
              <h2 className="art:mt-4 art:font-sans art:font-medium art:text-4xl art:text-foreground art:leading-none art:tracking-tight">
                <span className="art:block">
                  {copy.headline}
                </span>
                {accent ? (<>
                {" "}
                <span className="art:block">
                  {accent}
                </span>
                </>) : null}
              </h2>
              {copy.subhead ? (<p className="art:mx-auto art:mt-4 art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
                {copy.subhead}
              </p>) : null}
            </div>
            <div className="art:relative art:mt-12 art:grid art:border art:border-border art:@min-[640px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:grid-cols-3">
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:right-full art:-top-px art:z-10 art:h-0 art:w-3 art:border-border art:border-t"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:bottom-full art:-left-px art:z-10 art:h-3 art:w-0 art:border-border art:border-l"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:left-full art:-top-px art:z-10 art:h-0 art:w-3 art:border-border art:border-t"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:-right-px art:bottom-full art:z-10 art:h-3 art:w-0 art:border-border art:border-l"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:right-full art:-bottom-px art:z-10 art:h-0 art:w-3 art:border-border art:border-t"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:top-full art:-left-px art:z-10 art:h-3 art:w-0 art:border-border art:border-l"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:left-full art:-bottom-px art:z-10 art:h-0 art:w-3 art:border-border art:border-t"/>
              <span aria-hidden="true" className="art:pointer-events-none art:absolute art:top-full art:-right-px art:z-10 art:h-3 art:w-0 art:border-border art:border-l"/>
              {items.map((item, i) => {
            const Icon = item.icon ?? ICONS[i % ICONS.length];
            const [lead, ...rest] = item.title.split(" ");
            return (<motion.article key={i} className={cardClass(i, items.length)} {...reveal(i)}>
                <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0">
                  <CardFx index={i} hovered={hovered === i}/>
                  <div className="art:absolute art:inset-0 art:bg-gradient-to-b art:from-background art:via-background/80 art:to-background/25"/>
                </div>
                <div className="art:relative art:z-10 art:flex art:h-full art:flex-col">
                  <span className="art:grid art:size-11 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                    <Icon className="art:size-4.5"/>
                  </span>
                  <h3 className="art:mt-5 art:font-medium art:text-foreground art:text-xl art:leading-snug art:tracking-tight">
                    <span className="art:block">
                      {lead}
                    </span>
                    {rest.length ? (<>
                    {" "}
                    <span className="art:block">
                      {rest.join(" ")}
                    </span>
                    </>) : null}
                  </h3>
                  <p className="art:mt-2 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                    {item.description}
                  </p>
                </div>
              </motion.article>);
        })}
            </div>
          </div>
        </section>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { MeshGradient } from "@paper-design/shaders-react";
import { AnimatePresence, motion } from "motion/react";
import { useEffect, useState } from "react";
import { ARTEMIS_EASE_IN_OUT, ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const PALETTES: readonly string[][] = [
    ["#f9d5b4", "#f4b6c8", "#c9b8ee", "#9ed5ea", "#b7e6d1"],
    ["#d9efcf", "#a9dcd3", "#a9d3ef", "#c6b7e9", "#efbfd0"],
    ["#f4d7aa", "#efb8a8", "#d1b9e8", "#add9e3", "#c4e3c4"],
];
const FX_HIDDEN = { clipPath: "inset(86% 0px 0%)", opacity: 0, transform: "translateY(30%) scaleY(0.72)" };
const FX_SHOWN = { clipPath: "inset(0% 0px)", opacity: 0.58, transform: "translateY(0%) scaleY(1)" };
const FX_EXIT = {
    clipPath: "inset(86% 0px 0%)",
    opacity: 0,
    transform: "translateY(24%) scaleY(0.82)",
    transition: { duration: 0.18, ease: ARTEMIS_EASE_OUT },
};
const ENTER = { duration: 0.48, delay: 0.03, ease: ARTEMIS_EASE_IN_OUT };
const LEAVE = { duration: 0.18, ease: ARTEMIS_EASE_OUT };
const UNMOUNT_MS = 220;
export function CardFx({ index, hovered }: {
    index: number;
    hovered: boolean;
}) {
    const [mounted, setMounted] = useState(false);
    useEffect(() => {
        if (hovered) {
            setMounted(true);
            return undefined;
        }
        const t = window.setTimeout(() => setMounted(false), UNMOUNT_MS);
        return () => window.clearTimeout(t);
    }, [hovered]);
    return (<AnimatePresence>
      {mounted ? (<motion.div key="fx" aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-[-16%] art:-bottom-16 art:h-[112%] art:origin-bottom art:will-change-[transform,opacity,clip-path] art:[mask-image:linear-gradient(to_top,black_0%,black_44%,transparent_88%)]" initial={FX_HIDDEN} animate={hovered ? FX_SHOWN : FX_HIDDEN} exit={FX_EXIT} transition={hovered ? ENTER : LEAVE}>
          <div className="art:size-full">
            <MeshGradient className="art:size-full" colors={PALETTES[index % 3]} distortion={1.18} swirl={0.72} grainMixer={0.08} grainOverlay={0.035} speed={0.32} scale={1.16} offsetY={0.2} fit="contain" minPixelRatio={1} maxPixelCount={180000}/>
          </div>
        </motion.div>) : null}
    </AnimatePresence>);
}
